import { api } from './api.js';
import { escapeHTML as e } from '../ui.js';
import { loadExcelJS } from './timetable-xlsx.js';
const labels={present:'Có mặt',late:'Đi muộn',excused:'Nghỉ có phép',unexcused:'Nghỉ không phép'};
function chart(report){
 const count=report.attendanceCount;
 const bars=Object.entries(report.attendance).map(([k,v])=>`<div><span>${labels[k]}: ${v}${count?` (${Math.round(v/count*100)}%)`:''}</span><div style="background:var(--surface-2);height:16px"><div style="background:var(--primary);height:100%;width:${count?v/count*100:0}%"></div></div></div>`).join('');
 const series=new Map();for(const r of report.trend){const key=r.subject+' · '+r.term;const arr=series.get(key)||[];arr.push(r);series.set(key,arr);}
 const graphs=[...series].map(([key,rows])=>{const points=rows.map((r,i)=>`${40+i*510/Math.max(1,rows.length-1)},${220-r.average*20}`).join(' ');return `<h4>${e(key)}</h4><svg viewBox="0 0 600 270" role="img" aria-label="${e(key)}: điểm trung bình theo ngày nhập" style="max-width:100%;width:600px;color:var(--text)"><path d="M40 20V220H570" fill="none" stroke="currentColor"/><text x="5" y="25" fill="currentColor">10</text><text x="15" y="220" fill="currentColor">0</text><polyline points="${points}" fill="none" stroke="var(--primary)" stroke-width="3"/>${rows.map((r,i)=>{const x=40+i*510/Math.max(1,rows.length-1),y=220-r.average*20;return `<circle cx="${x}" cy="${y}" r="4" fill="var(--primary)"><title>${e(r.date)}: ${r.average}/10 · ${r.sampleSize} học sinh</title></circle>`;}).join('')}<text x="40" y="250" fill="currentColor">${e(rows[0].date)}</text><text x="460" y="265" fill="currentColor">${e(rows.at(-1).date)}</text></svg><details><summary>Xem dữ liệu biểu đồ</summary>${rows.map(r=>`<p>${e(r.date)}: ${r.average}/10 · ${r.sampleSize} học sinh</p>`).join('')}</details>`;}).join('');
 return `<div class="grid two"><section><h3>Chuyên cần: ${report.attendanceRate==null?'Chưa có dữ liệu':report.attendanceRate+'%'}</h3>${bars}</section><section><h3>Tiến bộ theo môn / học kỳ</h3>${graphs||'<p>Chưa có điểm trong sổ điểm để vẽ biểu đồ.</p>'}</section></div>`;
}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
export function mountSchoolReports(root,{url,feedbackUrl}){
 const controller=new AbortController();let report;
 root.innerHTML='<section class="portal-panel"><h2>Biểu đồ và báo cáo học tập</h2><p role="status" data-report-status>Đang tổng hợp…</p><div data-report-content></div></section>';
 const status=root.querySelector('[data-report-status]'),content=root.querySelector('[data-report-content]');
 api(url,{signal:controller.signal}).then(data=>{if(!root.isConnected)return;report=data;status.textContent='';const names=new Map(data.students.map(s=>[String(s.id),s.name]));content.innerHTML=`<p class="muted">${e(data.note)}</p>${chart(data)}<div class="inline-actions"><button class="button secondary" type="button" data-report-pdf>Xuất PDF</button><button class="button secondary" type="button" data-report-excel>Xuất Excel</button></div><h3>Kết quả theo học sinh / môn</h3>${data.summaries.map(s=>`<p>${e(names.get(String(s.studentId))||'')} · ${e(s.subject)} · ${e(s.term)}: <strong>${s.average}/10</strong> (${s.count} cột điểm)</p>`).join('')||'<p>Chưa có điểm đã nhập.</p>'}${data.records.length?`<details><summary>Chi tiết cột điểm và chuyên cần (${data.records.length})</summary>${data.records.map(r=>{const p=r.payload;return `<p>${e(names.get(String(r.student_id))||'')} · ${r.kind==='grade'?`${e(p.subject)} · ${e(p.term)} · ${e(p.title)}: ${e(p.score)}/10 · hệ số ${e(p.weight)}`:`${e(p.date)} · ${e(p.session)} · ${e(labels[p.status])}`}</p>`;}).join('')}</details>`:''}${feedbackUrl?'<form data-student-feedback class="portal-form"><h3>Feedback riêng cho học sinh</h3><label>Nhận xét<textarea name="message" maxlength="4000" rows="5" required></textarea></label><button class="button primary">Gửi thông báo riêng</button></form>':''}`;}).catch(err=>{if(!controller.signal.aborted)status.textContent=err.message;});
 root.addEventListener('click',async ev=>{const b=ev.target.closest('[data-report-pdf],[data-report-excel]');if(!b||!report)return;b.disabled=true;try{if(b.hasAttribute('data-report-pdf')){const u=new URL(url,location.origin);u.searchParams.set('format','pdf');const response=await fetch(u,{credentials:'same-origin',signal:controller.signal});if(!response.ok)throw new Error('Không xuất được PDF.');download(await response.blob(),'maihoc-report.pdf');}else{const ExcelJS=await loadExcelJS(),book=new ExcelJS.Workbook(),names=new Map(report.students.map(s=>[String(s.id),s.name]));const sheet=(name,rows)=>{const s=book.addWorksheet(name);rows.forEach(r=>s.addRow(r));s.getRow(1).font={bold:true};s.columns.forEach(c=>c.width=24);};sheet('Tổng hợp',[['Học sinh','Môn','Học kỳ','Trung bình /10','Số cột'],...report.summaries.map(r=>[names.get(String(r.studentId)),r.subject,r.term,r.average,r.count])]);sheet('Điểm và chuyên cần',[['Học sinh','Loại','Tiêu đề','Môn','Học kỳ','Điểm','Hệ số','Ngày','Buổi','Trạng thái'],...report.records.map(r=>{const p=r.payload;return [names.get(String(r.student_id)),r.kind,p.title,p.subject||'',p.term||'',p.score??'',p.weight??'',p.date||'',p.session||'',labels[p.status]||''];})]);sheet('Biểu đồ',[['Ngày nhập','Môn','Học kỳ','Điểm trung bình','Số học sinh'],...report.trend.map(r=>[r.date,r.subject,r.term,r.average,r.sampleSize])]);sheet('Hoạt động',[['Học sinh','Nội dung','Môn','Trạng thái','Tiến độ %','Điểm gốc','Cập nhật'],...report.activities.map(r=>[names.get(String(r.student_id)),r.item_title,r.subject,r.status,r.progress_percent,r.score,r.updated_at])]);sheet('Ghi chú',[['Phạm vi và cách tính'],[report.note],['Chuyên cần %',report.attendanceRate??'Chưa có dữ liệu'],['Số lượt điểm danh',report.attendanceCount]]);download(new Blob([await book.xlsx.writeBuffer()],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}),'maihoc-report.xlsx');}status.textContent='Đã xuất báo cáo.';}catch(err){status.textContent=err.message;}finally{b.disabled=false;}},{signal:controller.signal});
 root.addEventListener('submit',async ev=>{const form=ev.target;if(!form.matches('[data-student-feedback]'))return;ev.preventDefault();ev.stopPropagation();const b=form.querySelector('button');b.disabled=true;try{await api(feedbackUrl,{method:'POST',body:{message:form.elements.message.value},signal:controller.signal});form.reset();status.textContent='Đã gửi feedback riêng vào thông báo của học sinh.';}catch(err){status.textContent=err.message;}finally{b.disabled=false;}},{signal:controller.signal});
 return ()=>controller.abort();
}
